create schema if not exists extensions;
alter extension btree_gist set schema extensions;
drop policy if exists "owners manage services" on public.services;
create policy "owners insert services" on public.services for insert to authenticated with check(exists(select 1 from public.businesses b where b.id=services.business_id and b.owner_id=(select auth.uid())));
create policy "owners update services" on public.services for update to authenticated using(exists(select 1 from public.businesses b where b.id=services.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=services.business_id and b.owner_id=(select auth.uid())));
create policy "owners delete services" on public.services for delete to authenticated using(exists(select 1 from public.businesses b where b.id=services.business_id and b.owner_id=(select auth.uid())));
