create policy "owners update business hours" on public.business_hours for update to authenticated using(exists(select 1 from public.businesses b where b.id=business_hours.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=business_hours.business_id and b.owner_id=(select auth.uid())));
create policy "owners delete business hours" on public.business_hours for delete to authenticated using(exists(select 1 from public.businesses b where b.id=business_hours.business_id and b.owner_id=(select auth.uid())));
