create index if not exists appointments_service_id_idx on public.appointments(service_id);
revoke all on function public.admin_review_business(uuid,text) from public,anon;
grant execute on function public.admin_review_business(uuid,text) to authenticated;
revoke all on function public.book_appointment(uuid,uuid,uuid,timestamptz,text) from public,anon;
grant execute on function public.book_appointment(uuid,uuid,uuid,timestamptz,text) to authenticated;